from distutils.version import LooseVersion
from packaging.version import Version, InvalidVersion
cases = [('0.6.0','0.10.0'), ('0.6','0.10'), ('1.3.4','1.10'), ('1.0','0.9'), ('1.0a1','1.0'), ('builtin','0.1'), ('unknown version','0.1')]
for a,b in cases:
    print('Case', a, b)
    for cls in (LooseVersion, Version):
        try:
            va, vb = cls(a), cls(b)
            print(' ', cls.__module__, cls.__name__, 'result', va > vb, 'objs', va, vb)
        except Exception as e:
            print(' ', cls.__module__, cls.__name__, 'ERROR', type(e).__name__, e)
